referenceSolutions.python:
def duplicateCarriageBossReceipt(readings):
    a=readings
    out=[]
    write=0
    for read in range(len(a)):
        if write==0 or a[read]!=a[write-1]:
            a[write]=a[read]
            write+=1
    out=a[:write]
    return sum((i+1)*x for i,x in enumerate(out))

